# patch270 : l'atelier des cartes, V1 (finitions et halos), caché jusqu'à s2-64
# Aperçus validés : canevas « Atelier des cartes TerraFront » (21/10), Chrome et Cristal (29/10),
# l'achat depuis l'atelier (29/10, « c'est parfait »).
# Une composition (finition + halo + couleur) posée sur toutes les cartes Terra du joueur :
# collection, fiche, bilan du paquet, révélation, vitrine (la sienne et celle des autres).
# Encre et Lueur se gagnent ; Chrome, Cristal, Étoiles, Braises s'achètent (boutique en euros, type « effet »).
# Essai privé avant s2-64 : ajouter ?atelier=test à l'adresse du jeu (cet onglet seulement, achats simulés).
import pathlib
def rep(s, a, b, n=1):
    assert s.count(a) == n, (a[:90], s.count(a)); return s.replace(a, b)
JS = "\n// ---------- patch270 : l'atelier des cartes, V1 (s2-64) ----------\n// Une composition posée sur toutes mes cartes Terra : une finition (Encre,\n// Chrome, Cristal ; Or plus tard) et un halo (Lueur, Étoiles, Braises) avec\n// sa couleur. Encre et Lueur se gagnent en jouant ; Chrome, Cristal, Étoiles\n// et Braises s'achètent à l'unité (boutique en euros, articles « effet »).\n// Une brillante ou un éclat garde sa propre lumière ; une carte qui porte un\n// skin garde son skin (seul le halo s'ajoute) ; jamais le Front.\n// Dans une grille : la finition reste immobile et le halo est une lueur fixe\n// (des centaines de cartes) ; en grand (fiche, atelier, révélation, vitrine),\n// tout s'anime. Caché tant que atelier_etat() n'existe pas (s2-64).\n// Essai privé avant l'annonce : ?atelier=test (cet onglet seulement).\nconst ATL_FINITIONS = [\n  { id: 'aucune', nom: 'Aucune', src: 'inclus' },\n  { id: 'encre', nom: 'Encre', src: 'gagner', comment: '50 quêtes du jour' },\n  { id: 'chrome', nom: 'Chrome', src: 'boutique', article: 'atelier-chrome', prix: 299 },\n  { id: 'cristal', nom: 'Cristal', src: 'boutique', article: 'atelier-cristal', prix: 299 },\n  { id: 'or', nom: 'Or', src: 'pass', comment: 'Pass de saison · bientôt' }\n];\nconst ATL_HALOS = [\n  { id: 'aucun', nom: 'Aucun', src: 'inclus' },\n  { id: 'lueur', nom: 'Lueur', src: 'gagner', comment: 'Série de 7 jours' },\n  { id: 'etoiles', nom: 'Étoiles', src: 'boutique', article: 'atelier-etoiles', prix: 199 },\n  { id: 'braises', nom: 'Braises', src: 'boutique', article: 'atelier-braises', prix: 199 }\n];\nconst ATL_FAMILLES = [{ id: 'finition', lib: 'Finition', options: ATL_FINITIONS }, { id: 'halo', lib: 'Halo', options: ATL_HALOS }];\nconst ATL_COULEURS = [\n  { id: 'or', c: '#FFE08A', lib: 'Or pâle' }, { id: 'ciel', c: '#7FD4FF', lib: 'Ciel' },\n  { id: 'corail', c: '#FF8A80', lib: 'Corail' }, { id: 'vert', c: '#B8F27A', lib: 'Tilleul' },\n  { id: 'mauve', c: '#E3B8FF', lib: 'Mauve' }\n];\nconst ATL_CADENAS = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"5\" y=\"11\" width=\"14\" height=\"10\" rx=\"2\"></rect><path d=\"M8 11V8a4 4 0 0 1 8 0v3\"></path></svg>';\nconst ATL = { lu: false, ouvert: false, test: false, moi: null, possede: {}, quetes: null, serie: null, encreQuetes: 50, lueurJours: 7, pret: null };\n\nfunction atlTest(){\n  try{\n    if(/[?&]atelier=test\\b/.test(location.search)) sessionStorage.setItem('tf-atl-test', '1');\n    return sessionStorage.getItem('tf-atl-test') === '1';\n  }catch(e){ return false; }\n}\nfunction atlLireEtat(d){\n  const c = (d && d.composition) || {};\n  ATL.lu = true;\n  ATL.ouvert = d.ouvert === true || Number(d.ouvert) === 1;\n  ATL.moi = { finition: c.finition || 'aucune', halo: c.halo || 'aucun', couleur: c.couleur || 'or' };\n  ATL.possede = d.possede || {};\n  ATL.quetes = d.quetes != null ? Number(d.quetes) : null;\n  ATL.serie = d.serie != null ? Number(d.serie) : null;\n  ATL.encreQuetes = Number(d.encre_quetes) || 50;\n  ATL.lueurJours = Number(d.lueur_jours) || 7;\n}\nfunction atlCharger(){\n  ATL.pret = (async () => {\n    if(!SAISON2) return;\n    if(atlTest()){\n      let moi = null;\n      try{ moi = JSON.parse(sessionStorage.getItem('tf-atl-test-moi') || 'null'); }catch(e){}\n      Object.assign(ATL, { lu: true, ouvert: true, test: true, moi: moi || { finition: 'aucune', halo: 'aucun', couleur: 'or' },\n        possede: { encre: true }, quetes: null, serie: null });\n      if(!ATL.annonce){\n        ATL.annonce = true;\n        setTimeout(() => notifier({ type: 'info', titre: 'Essai de l’atelier',\n          texte: 'Dans cet onglet seulement : les achats sont simulés (rien n’est payé) et ta composition n’est gardée qu’ici. Ferme l’onglet pour en sortir.' }), 1800);\n      }\n    } else {\n      try{\n        const { data, error } = await sb.rpc('atelier_etat');\n        if(error || !data) return;   // s2-64 pas encore lancé : rien ne s'affiche\n        atlLireEtat(data);\n      }catch(e){ return; }\n    }\n    try{ if(gardeRobe && document.getElementById('grCorps')) renderGardeRobe(); }catch(e){}\n  })();\n  return ATL.pret;\n}\n\n// ma composition, telle qu'elle se pose sur mes cartes (null = rien à poser)\nfunction atlMienne(niveau){\n  const c = ATL.ouvert ? ATL.moi : null;\n  if(!c || (c.finition === 'aucune' && c.halo === 'aucun')) return null;\n  return { finition: c.finition, halo: c.halo, couleur: c.couleur, niveau: niveau || 0 };\n}\n// une de mes cartes Terra de la collection (une carte avec un skin garde son skin)\nfunction atlMoi(e, niveau){\n  const a = atlMienne(niveau);\n  if(!a) return e;\n  if(a.finition !== 'aucune' && skinDeMaCarte('terra', e.code)) a.finition = 'aucune';\n  return a.finition === 'aucune' && a.halo === 'aucun' ? e : { ...e, atelier: a };\n}\nconst atlNiveau = (a, n) => a ? { ...a, niveau: n } : a;\n\n// les étoiles ou les braises autour d'une carte en grand\nfunction atlParticules(halo, code, niv, grande){\n  if((halo !== 'etoiles' && halo !== 'braises') || REDUCED_MOTION) return '';\n  const rnd = aleatoireStable(hashTexte(String(code) + halo));\n  const k = grande ? 1 : niv > 1 ? 0.8 : 0.45;\n  const n = niv > 1 ? (halo === 'etoiles' ? 16 : 18) : 6;\n  let h = '';\n  for(let i = 0; i < n; i++){\n    if(halo === 'etoiles'){\n      const dir = niv > 1 ? i % 8 : (i * 3) % 8, a = dir * Math.PI / 4 + (rnd() - 0.5) * 0.4, d = 40 * k;\n      h += `<i class=\"atl-p etoile\" style=\"left:${(50 + Math.cos(a) * 40).toFixed(1)}%;top:${(50 + Math.sin(a) * 45).toFixed(1)}%;`\n        + `--dx:${(Math.cos(dir * Math.PI / 4) * d).toFixed(1)}px;--dy:${(Math.sin(dir * Math.PI / 4) * d).toFixed(1)}px;animation-delay:${(rnd() * 2.6).toFixed(2)}s\"></i>`;\n    } else {\n      h += `<i class=\"atl-p braise\" style=\"left:${(14 + rnd() * 72).toFixed(1)}%;top:${(70 + rnd() * 22).toFixed(1)}%;`\n        + `--dx:${(((i % 3) - 1) * 22 * k).toFixed(1)}px;--dy:${(-(150 + (i % 3 === 1 ? 10 : 0)) * k).toFixed(1)}px;animation-delay:${(rnd() * 3).toFixed(2)}s\"></i>`;\n    }\n  }\n  return `<i class=\"atl-parts\" aria-hidden=\"true\">${h}</i>`;\n}\nfunction atlScint(niv){\n  const n = niv > 1 ? 7 : 3;\n  let h = '';\n  for(let i = 1; i <= n; i++) h += `<i class=\"s${i}\"></i>`;\n  return `<i class=\"atl-scint\" aria-hidden=\"true\">${h}</i>`;\n}\n// les calques d'une carte : derrière (halo), au fond de la carte, dans l'image, par-dessus\nfunction atlParts(e, grande){\n  const vide = { cls: '', dehors: '', fond: '', art: '', anneau: '' };\n  const a = e && e.atelier;\n  if(!a || (e.brillantes || 0) > 0 || e.brillante || e.eclat) return vide;\n  const fn = !e.skin && ATL_FINITIONS.some(o => o.id === a.finition) ? a.finition : 'aucune';\n  const ha = ATL_HALOS.some(o => o.id === a.halo) ? a.halo : 'aucun';\n  if(fn === 'aucune' && ha === 'aucun') return vide;\n  const col = ATL_COULEURS.some(o => o.id === a.couleur) ? a.couleur : 'or';\n  const niv = grande ? 2 : (Number(a.niveau) || 0);\n  return {\n    cls: ` atl fn-${fn} h-${ha} hc-${col}${niv ? ' atl-n' + niv : ''}`,\n    dehors: (ha !== 'aucun' && niv > 0 ? '<i class=\"atl-glow\" aria-hidden=\"true\"></i>' : '') + (niv > 0 ? atlParticules(ha, e.code, niv, grande) : ''),\n    fond: fn !== 'aucune' ? '<i class=\"atl-fond\" aria-hidden=\"true\"></i>' : '',\n    art: fn !== 'aucune' ? '<i class=\"atl-a1\" aria-hidden=\"true\"></i><i class=\"atl-a2\" aria-hidden=\"true\"></i>' : '',\n    anneau: (fn !== 'aucune' ? '<i class=\"atl-reflet\" aria-hidden=\"true\"></i>' : '') + (fn === 'cristal' && niv > 0 && !REDUCED_MOTION ? atlScint(niv) : '')\n  };\n}\n\n// la vitrine d'un joueur : sa composition sur ses cartes Terra\nasync function atlVitrine(id, cartes){\n  if(!ATL.lu || !ATL.ouvert || !cartes || !cartes.length) return cartes;\n  let comp = null;\n  if(id === window.__monId) comp = atlMienne(1);\n  else if(!ATL.test){\n    try{\n      const { data, error } = await sb.rpc('atelier_composition', { p_joueur: id });\n      if(!error && data) comp = { finition: data.finition || 'aucune', halo: data.halo || 'aucun', couleur: data.couleur || 'or', niveau: 1 };\n    }catch(e){}\n  }\n  if(comp && (comp.finition !== 'aucune' || comp.halo !== 'aucun'))\n    for(const c of cartes) if(c.source !== 'front') c.atelier = { ...comp };\n  return cartes;\n}\n\n// ---------- l'écran de l'atelier ----------\nconst AS = { finition: 'aucune', halo: 'aucun', couleur: 'or', carte: 0, cartes: [], onglet: 'finition', achats: {}, eclat: false, enCours: false, minuteur: 0 };\nlet atlRetourFocus = null;\n\nfunction atlPossede(id){\n  if(id === 'aucune' || id === 'aucun') return true;\n  if(ATL.test && AS.achats[id]) return true;\n  return !!(ATL.possede && ATL.possede[id]);\n}\nfunction atlArticle(o){\n  const cat = bqeCat;\n  return (o && o.article && cat && (cat.articles || []).find(a => a.id === o.article)) || null;\n}\nfunction atlPrix(o){ const a = atlArticle(o); return euros(a ? bqePrixMoi(a) : o.prix); }\nfunction atlSource(o){\n  if(o.src === 'boutique') return 'à acheter ici ou dans la Boutique, ' + atlPrix(o) + ', à l’unité';\n  if(o.src === 'pass') return 'arrivera dans un prochain pass de saison';\n  if(o.id === 'encre') return `se gagne en jouant (${ATL.encreQuetes} quêtes du jour réclamées)`\n    + (ATL.quetes != null ? ` · tu en es à ${fmtNombre(Math.min(ATL.quetes, ATL.encreQuetes))}` : '');\n  if(o.id === 'lueur') return `se gagne en jouant (une quête du jour réclamée ${ATL.lueurJours} jours d’affilée)`\n    + (ATL.serie != null ? ` · ta meilleure série : ${ATL.serie} jour${ATL.serie > 1 ? 's' : ''}` : '');\n  return '';\n}\nconst atlCommentaire = (o) => o.comment ? o.comment.charAt(0).toLowerCase() + o.comment.slice(1) : '';\n// les éléments choisis qui ne sont pas encore à moi\nfunction atlManquants(){\n  const out = [];\n  for(const f of ATL_FAMILLES){\n    const o = f.options.find(x => x.id === AS[f.id]);\n    if(!o || atlPossede(o.id)) continue;\n    const art = atlArticle(o);\n    out.push({ f, o, attente: art && art.livraison_le ? art.livraison_le : null });\n  }\n  return out;\n}\n// une carte de chaque rareté pour essayer : mes plus connues (ni brillante, ni éclat, ni skin)\nfunction atlCartesEssai(){\n  const out = [];\n  try{\n    if(terraCollection && terraCollection.size) for(const t of TIERS){\n      let best = null;\n      for(const e of terraCollection.values()){\n        if(e.tier.id !== t.id || (e.brillantes || 0) > 0 || e.eclat || skinDeMaCarte('terra', e.code)) continue;\n        if(!best || (e.pop || 0) > (best.pop || 0)) best = e;\n      }\n      if(best) out.push(best);\n    }\n  }catch(e){}\n  if(!out.length) out.push(carteExemple());\n  return out;\n}\nconst atlNomCourt = (n) => String(n || '').length > 16 ? String(n).slice(0, 14).trimEnd() + '…' : String(n || '');\n\nfunction atlOuvrir(){\n  if(!ATL.lu || !ATL.ouvert) return;\n  const m = ATL.moi || {};\n  Object.assign(AS, { finition: m.finition || 'aucune', halo: m.halo || 'aucun', couleur: m.couleur || 'or', carte: 0, onglet: 'finition', eclat: false, enCours: false });\n  AS.cartes = atlCartesEssai();\n  let ec = document.getElementById('atlEcran');\n  if(!ec){\n    ec = document.createElement('div');\n    ec.id = 'atlEcran';\n    ec.className = 'atl-ecran';\n    ec.setAttribute('role', 'dialog');\n    ec.setAttribute('aria-modal', 'true');\n    ec.setAttribute('aria-labelledby', 'atlTitre');\n    ec.hidden = true;\n    document.body.appendChild(ec);\n    ec.addEventListener('click', atlClic);\n  }\n  if(ec.hidden) atlRetourFocus = document.activeElement;\n  document.documentElement.classList.add('atl-ouvert');\n  ec.hidden = false;\n  atlRendre();\n  document.removeEventListener('keydown', atlTouche);\n  document.addEventListener('keydown', atlTouche);\n  requestAnimationFrame(() => {\n    ec.classList.add('visible');\n    const r = ec.querySelector('.atl-retour');\n    if(r) try{ r.focus({ preventScroll: true }); }catch(e){}\n  });\n  // les prix du catalogue, et mes cartes pour l'essai\n  if(!ATL.test && bqeAcces === null) bqeVerifierAcces().then(() => { if(!ec.hidden) atlRendre(); }).catch(() => {});\n  if(!terraCharge) chargerCollectionTerra().then(ok => { if(ok && !ec.hidden){ AS.cartes = atlCartesEssai(); atlRendre(); } }).catch(() => {});\n}\nfunction atlFermer(){\n  const ec = document.getElementById('atlEcran');\n  if(!ec || ec.hidden) return;\n  clearTimeout(AS.minuteur);\n  ec.classList.remove('visible');\n  ec.hidden = true;\n  ec.innerHTML = '';\n  document.documentElement.classList.remove('atl-ouvert');\n  document.removeEventListener('keydown', atlTouche);\n  if(atlRetourFocus && atlRetourFocus.isConnected && atlRetourFocus.focus) try{ atlRetourFocus.focus({ preventScroll: true }); }catch(e){}\n  try{ if(gardeRobe && document.getElementById('grCorps')) renderGardeRobe(); }catch(e){}\n}\nfunction atlTouche(e){\n  if(e.key !== 'Escape') return;\n  const f = document.getElementById('fenetre');\n  if(f && !f.hidden) return;   // la fiche d'achat se ferme d'abord\n  atlFermer();\n}\nasync function atlOuvrirQuandPret(){\n  try{ await atlCharger(); }catch(e){}\n  atlOuvrir();\n}\n\nfunction atlCouleursHtml(){\n  return `<div class=\"atl-couleurs\"><p class=\"atl-lbl\">Couleur du halo</p><div class=\"atl-sws\">${ATL_COULEURS.map(h =>\n    `<button type=\"button\" class=\"atl-sw${AS.couleur === h.id ? ' on' : ''}\" aria-pressed=\"${AS.couleur === h.id}\" aria-label=\"Halo ${h.lib}\" data-atl-c=\"${h.id}\" data-atl-k=\"c-${h.id}\"><span style=\"background:${h.c}\"></span></button>`).join('')}</div></div>`;\n}\nfunction atlRendre(){\n  const ec = document.getElementById('atlEcran');\n  if(!ec || ec.hidden) return;\n  const actif = document.activeElement && ec.contains(document.activeElement) ? document.activeElement.dataset.atlK : null;\n  const page = ec.querySelector('.atl-page'), defil = page ? page.scrollTop : 0;\n  const s = AS, manq = atlManquants(), n = manq.length;\n  const achat = manq.find(m => m.o.src === 'boutique' && !m.attente) || null;\n  const moi = ATL.moi || { finition: 'aucune', halo: 'aucun', couleur: 'or' };\n  const egal = s.finition === moi.finition && s.halo === moi.halo && (s.halo === 'aucun' || s.couleur === moi.couleur);\n  const fait = egal && !(moi.finition === 'aucune' && moi.halo === 'aucun') ? 'Composition enregistrée' : 'Enregistrer';\n  const familles = ATL_FAMILLES.map(f => {\n    const opts = f.options.map(o => {\n      const sel = s[f.id] === o.id, aMoi = atlPossede(o.id), art = atlArticle(o);\n      const attente = !aMoi && art && art.livraison_le;\n      const badge = aMoi ? (o.src === 'inclus' ? 'Inclus' : 'À toi') : attente ? 'Arrive le ' + dateLongue(art.livraison_le) : o.src === 'boutique' ? atlPrix(o) : o.comment;\n      const bcls = 'atl-badge b-' + (aMoi ? (o.src === 'inclus' ? 'inclus' : 'atoi') : o.src);\n      return `<button type=\"button\" class=\"atl-opt${sel ? ' on' : ''}${aMoi ? '' : ' verrou'}\" aria-pressed=\"${sel}\" data-atl-f=\"${f.id}\" data-atl-o=\"${o.id}\" data-atl-k=\"o-${f.id}-${o.id}\">`\n        + `<span class=\"atl-opt-nom\">${o.nom}</span><span class=\"${bcls}\">${aMoi ? '' : ATL_CADENAS}${echapperTexte(badge)}</span></button>`;\n    }).join('');\n    const choisi = (f.options.find(o => o.id === s[f.id]) || f.options[0]).nom;\n    return `<div class=\"atl-fam${s.onglet === f.id ? ' actif' : ''}\" data-famille=\"${f.id}\">\n        <div class=\"atl-fam-tete\"><p class=\"atl-lbl\">${f.lib}</p><p class=\"atl-choisi\">${choisi}</p></div>\n        <div class=\"atl-opts\">${opts}</div>${f.id === 'halo' && s.halo !== 'aucun' ? atlCouleursHtml() : ''}\n      </div>`;\n  }).join('');\n  const c = s.cartes[s.carte] || s.cartes[0] || carteExemple();\n  const carte = { ...c, exemplaires: 1, skin: undefined, brillante: 0, brillantes: 0, numeros: [], eclat: !!s.eclat,\n    atelier: { finition: s.finition, halo: s.halo, couleur: s.couleur, niveau: 2 } };\n  const nomsManq = manq.map(m => m.o.nom).join(', ');\n  const scene = `<div class=\"atl-scene\">${s.eclat ? '<i class=\"atl-ec-rayons\" aria-hidden=\"true\"></i><i class=\"atl-ec-flash\" aria-hidden=\"true\"></i>' : ''}\n      <div class=\"atl-c3d\">${carte3dDebut(150, 225, 1.85)}${miniTerra(carte)}${carte3dFin()}</div>\n      ${n ? `<p class=\"atl-essai-pill\">Essai : ${echapperTexte(nomsManq)} ${n > 1 ? 'ne sont pas à toi' : 'n’est pas à toi'}</p>` : ''}</div>`;\n  const chips = s.cartes.length > 1 ? `<p class=\"atl-lbl atl-lbl-essayer\">Essayer sur une autre rareté</p><div class=\"atl-chips atl-chips-cartes\">${s.cartes.map((x, i) =>\n    `<button type=\"button\" class=\"atl-chip${i === s.carte ? ' on' : ''}\" aria-pressed=\"${i === s.carte}\" data-atl-carte=\"${i}\" data-atl-k=\"k-${i}\">${echapperTexte(atlNomCourt(x.nom))} · ${x.tier.label}</button>`).join('')}</div>` : '';\n  const essai = n ? `<div class=\"atl-essai\"><p class=\"atl-essai-t\">Aperçu d’essai</p>${manq.map(m =>\n    `<p><b>${m.f.lib} ${m.o.nom}</b> : ${m.attente ? 'déjà payé, arrive le ' + dateLongue(m.attente) : echapperTexte(atlSource(m.o))}</p>`).join('')}</div>` : '';\n  const onglets = `<div class=\"atl-onglets\" role=\"tablist\" aria-label=\"Familles d’effets\">${ATL_FAMILLES.map(f =>\n    `<button type=\"button\" role=\"tab\" class=\"atl-onglet${s.onglet === f.id ? ' on' : ''}\" aria-selected=\"${s.onglet === f.id}\" data-atl-onglet=\"${f.id}\" data-atl-k=\"t-${f.id}\">${f.lib}</button>`).join('')}</div>`;\n  const aObtenir = n + (n > 1 ? ' éléments à obtenir' : ' élément à obtenir');\n  const enrTexte = s.enCours ? 'Enregistrement…' : n ? 'Enregistrer · ' + aObtenir : fait;\n  const enrOff = s.enCours || n > 0 || egal ? ' disabled' : '';\n  const acheter = achat ? `Acheter ${achat.o.nom} · ${atlPrix(achat.o)}` : '';\n  const aGagner = manq.filter(m => m.o.src !== 'boutique');\n  const basTexte = achat ? `${achat.o.nom} est en vente, ici ou dans la Boutique`\n    : aGagner.length ? `${aGagner[0].o.nom} : ${atlCommentaire(aGagner[0].o)}`\n    : manq.length ? `${manq[0].o.nom} : déjà payé, arrive le ${dateLongue(manq[0].attente)}` : 'S’applique à toutes tes cartes Terra';\n  const eclat = BRI.lu && BRI.ouvert ? `<div class=\"atl-eclat\">\n      <div class=\"atl-eclat-t\"><p class=\"atl-eclat-h\">L’éclat d’une carte</p>\n        <p>Fonds ${BRI.eclatDoublons} doublons et ${fmtNombre(BRI.eclatTp)} TP pour donner un éclat à la carte de ton choix : des rayons dorés, une lumière qui fait le tour du cadre et le sceau « ✦ Éclat ». Ça se fait depuis la fiche de la carte ; l’exemplaire qui le porte ne s’échange plus.</p>\n        <p class=\"atl-eclat-v\">Se gagne avec tes doublons. Ne s’achète jamais en euros.</p></div>\n      <button type=\"button\" class=\"atl-btn sec\" data-atl=\"eclat\" data-atl-k=\"eclat\">Voir l’éclat</button></div>` : '';\n  ec.innerHTML = `<div class=\"atl-page\">\n    <div class=\"atl-tete\">\n      <button type=\"button\" class=\"atl-retour\" data-atl=\"fermer\" data-atl-k=\"fermer\" aria-label=\"Retour à Personnaliser\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M15 5l-7 7 7 7\"></path></svg></button>\n      <div class=\"atl-tete-t\"><p class=\"atl-fil\">Profil › Personnaliser › Mes cartes</p><h1 id=\"atlTitre\">L’atelier</h1>\n        <p class=\"atl-intro\">Compose l’apparence de tes cartes Terra. Essaie tout librement : tu n’enregistres que ce qui est à toi. Rien n’est tiré au hasard, rien ne s’échange, tout est gardé à vie.</p>\n        ${ATL.test ? '<p class=\"atl-test\"><span class=\"atl-test-l\">Essai : les achats sont simulés et rien n’est enregistré sur le serveur.</span><span class=\"atl-test-c\">Essai · achats simulés</span></p>' : ''}</div>\n    </div>\n    <div class=\"atl-corps\">\n      <div class=\"atl-gauche\">${scene}${chips}</div>\n      <div class=\"atl-droite\">${essai}${onglets}${familles}\n        <div class=\"atl-appliquer\">\n          <p class=\"atl-lbl\">Appliquer à</p>\n          <div class=\"atl-chips\"><span class=\"atl-seg on\">Toutes mes cartes Terra</span></div>\n          <div class=\"atl-actions\">${achat ? `<button type=\"button\" class=\"atl-btn\" data-atl=\"acheter\" data-atl-k=\"acheter\">${acheter}</button>` : ''}\n            <button type=\"button\" class=\"atl-btn${achat ? ' sec' : ''}\" data-atl=\"enregistrer\" data-atl-k=\"enregistrer\"${enrOff}>${enrTexte}</button></div>\n          <p class=\"atl-note\">Chaque élément s’obtient une seule fois et sert ensuite sur toutes tes cartes Terra. Ceux qui sont en vente s’achètent ici, ou dans la Boutique (Objets TerraFront) à côté des dos et des skins, avec le même paiement. Les cartes du Front changent de propriétaire : l’atelier ne s’y applique pas.</p>\n          <p class=\"atl-note\">${BRI.lu ? 'Tes brillantes et tes éclats gardent leur propre lumière. ' : ''}Sur une carte qui porte un skin, seul le halo s’ajoute.</p>\n        </div>\n      </div>\n    </div>${eclat}\n  </div>\n  <div class=\"atl-bas\"><p>${echapperTexte(basTexte)}</p>${achat\n    ? `<button type=\"button\" class=\"atl-btn\" data-atl=\"acheter\" data-atl-k=\"acheter-b\">${acheter}</button>`\n    : `<button type=\"button\" class=\"atl-btn\" data-atl=\"enregistrer\" data-atl-k=\"enregistrer-b\"${enrOff}>${s.enCours ? 'Enregistrement…' : n ? aObtenir : fait}</button>`}</div>`;\n  const p2 = ec.querySelector('.atl-page');\n  if(p2 && defil) p2.scrollTop = defil;\n  armerCarte3d(ec.querySelector('.atl-scene .c3d'));\n  if(actif){\n    const b = ec.querySelector(`[data-atl-k=\"${actif}\"]`);\n    if(b && !b.disabled) try{ b.focus({ preventScroll: true }); }catch(e){}\n  }\n}\nfunction atlClic(e){\n  const t = e.target.closest('[data-atl], [data-atl-f], [data-atl-c], [data-atl-carte], [data-atl-onglet]');\n  if(!t || t.disabled) return;\n  if(t.dataset.atlF){ AS[t.dataset.atlF] = t.dataset.atlO; AS.eclat = false; atlRendre(); return; }\n  if(t.dataset.atlC){ AS.couleur = t.dataset.atlC; atlRendre(); return; }\n  if(t.dataset.atlCarte != null){ AS.carte = Number(t.dataset.atlCarte) || 0; atlRendre(); return; }\n  if(t.dataset.atlOnglet){ AS.onglet = t.dataset.atlOnglet; atlRendre(); return; }\n  const a = t.dataset.atl;\n  if(a === 'fermer') atlFermer();\n  else if(a === 'enregistrer') atlEnregistrer();\n  else if(a === 'acheter') atlAcheter();\n  else if(a === 'eclat') atlVoirEclat();\n}\nasync function atlEnregistrer(){\n  if(AS.enCours || atlManquants().length) return;\n  const comp = { finition: AS.finition, halo: AS.halo, couleur: AS.couleur };\n  if(ATL.test){\n    ATL.moi = comp;\n    try{ sessionStorage.setItem('tf-atl-test-moi', JSON.stringify(comp)); }catch(e){}\n  } else {\n    AS.enCours = true; atlRendre();\n    let r;\n    try{ r = await sb.rpc('atelier_enregistrer', { p_finition: comp.finition, p_halo: comp.halo, p_couleur: comp.couleur }); }\n    catch(e){ r = { error: e }; }\n    AS.enCours = false;\n    if(r.error){\n      atlRendre();\n      notifier({ type: 'erreur', titre: 'Impossible d’enregistrer', texte: messageLisible(r.error.message) });\n      try{ await atlCharger(); }catch(e){}\n      atlRendre();\n      return;\n    }\n    if(r.data) atlLireEtat(r.data); else ATL.moi = comp;\n  }\n  atlRendre();\n  notifier({ type: 'succes', titre: 'Composition enregistrée',\n    texte: ATL.test ? 'Essai : elle n’est gardée que dans cet onglet.' : 'Elle est posée sur toutes tes cartes Terra.' });\n  try{ if(terraCharge && document.getElementById('tcGrille')) renderGrilleTerra(); }catch(e){}\n}\nasync function atlAcheter(){\n  const m = atlManquants().find(x => x.o.src === 'boutique' && !x.attente);\n  if(!m) return;\n  if(ATL.test){\n    AS.achats[m.o.id] = true;\n    atlRendre();\n    notifier({ type: 'info', titre: 'Essai : achat simulé', texte: `${m.f.lib} ${m.o.nom} : rien n’est payé, c’est pour voir. Tu peux enregistrer.` });\n    return;\n  }\n  try{ await bqeVerifierAcces(); }catch(e){}\n  const art = atlArticle(m.o);\n  if(!bqeAcces || !art){ notifier({ type: 'erreur', titre: 'Indisponible', texte: 'Cet élément n’est pas en vente pour le moment.' }); return; }\n  if(art.possede){ try{ await atlCharger(); }catch(e){} atlRendre(); return; }\n  bqeOuvrirFiche(art.id, 'atelier');\n}\nfunction atlVoirEclat(){\n  clearTimeout(AS.minuteur);\n  AS.eclat = true;\n  atlRendre();\n  try{ sonsOuverture.cloche(); }catch(e){}\n  AS.minuteur = setTimeout(() => { AS.eclat = false; atlRendre(); }, 4200);\n}\n\n// ---------- l'atelier dans la boutique et dans Personnaliser ----------\nfunction atlFamilleArticle(id){\n  const k = String(id || '').replace(/^atelier-/, '');\n  return ATL_HALOS.some(o => o.id === k) ? 'halo' : 'finition';\n}\n// pour montrer un objet seul (boutique, fiche d'achat) : Étoiles en ciel, Braises en corail\nfunction atlCompoArticle(id){\n  const k = String(id || '').replace(/^atelier-/, '');\n  return atlFamilleArticle(id) === 'halo' ? { finition: 'aucune', halo: k, couleur: k === 'braises' ? 'corail' : k === 'etoiles' ? 'ciel' : 'or' }\n    : { finition: k, halo: 'aucun', couleur: 'or' };\n}\nfunction atlVignetteHtml(id){\n  const ex = { ...carteExemple(), exemplaires: 1, aurore: 0, skin: undefined, brillantes: 0, numeros: [], eclat: false };\n  return `<div class=\"sk-vig atl-vig\" aria-hidden=\"true\"><div class=\"sk-vig-echelle\">${miniTerra({ ...ex, atelier: { ...atlCompoArticle(id), niveau: 2 } })}</div></div>`;\n}\nfunction atlGrandApercu(a){\n  const ex = { ...carteExemple(), exemplaires: 1, aurore: 0, skin: undefined, brillantes: 0, numeros: [], eclat: false };\n  return carte3dDebut(150, 225, 1.45) + miniTerra({ ...ex, atelier: { ...atlCompoArticle(a.id), niveau: 2 } }) + carte3dFin();\n}\nfunction atlQuoiAchat(a, nom){\n  return atlFamilleArticle(a.id) === 'halo'\n    ? `<b>le halo ${echapperTexte(nom)}</b> (5 couleurs au choix), à poser sur toutes tes cartes Terra`\n    : `<b>la finition ${echapperTexte(nom)}</b>, à poser sur toutes tes cartes Terra`;\n}\nfunction atlBlocGardeRobe(){\n  if(!ATL.lu || !ATL.ouvert) return '';\n  const m = ATL.moi || {};\n  const fn = ATL_FINITIONS.find(o => o.id === m.finition), ha = ATL_HALOS.find(o => o.id === m.halo);\n  const coul = ATL_COULEURS.find(x => x.id === m.couleur) || ATL_COULEURS[0];\n  const res = [];\n  if(fn && fn.id !== 'aucune') res.push('Finition ' + fn.nom);\n  if(ha && ha.id !== 'aucun') res.push('Halo ' + ha.nom + ' ' + coul.lib.toLowerCase());\n  const c = atlCartesEssai()[0];\n  return `<div class=\"gr-atelier\">\n      <div class=\"sk-vig gr-at-vig\" aria-hidden=\"true\"><div class=\"sk-vig-echelle\">${miniTerra({ ...c, exemplaires: 1, skin: undefined, atelier: atlMienne(1) })}</div></div>\n      <div class=\"gr-at-txt\"><b>L’atelier</b><span>${echapperTexte(res.length ? res.join(' · ') : 'Finitions et halos pour toutes tes cartes Terra')}</span>\n        <button type=\"button\" class=\"bq-btn\" data-gr-atelier>Ouvrir l’atelier</button></div>\n    </div>`;\n}\n"
CSS = "\n/* =====================================================================\n   patch270 — l'atelier des cartes, V1 : finitions et halos (s2-64)\n   Aperçus validés : canevas « Atelier des cartes TerraFront » (21/10),\n   Chrome et Cristal (29/10). Jamais d'arc-en-ciel : il est à la brillante.\n   Dans une grille, rien ne bouge (des centaines de cartes) ; en grand\n   (fiche, atelier, révélation, vitrine), la lumière suit la carte.\n   ===================================================================== */\n@property --atl-px { syntax: '<number>'; inherits: true; initial-value: 30; }\n@property --atl-py { syntax: '<number>'; inherits: true; initial-value: 26; }\n@keyframes atlBalade{ 0%, 100%{ --atl-px:22; --atl-py:30; } 50%{ --atl-px:78; --atl-py:70; } }\n\n.atl{ --atl-x:30%; --atl-y:26%; --halo:#FFE08A; }\n.atl.hc-ciel{ --halo:#7FD4FF; } .atl.hc-corail{ --halo:#FF8A80; } .atl.hc-vert{ --halo:#B8F27A; } .atl.hc-mauve{ --halo:#E3B8FF; }\n.mini.atl{ position:relative; }\n/* la lumière suit l'inclinaison de la carte en grand (fiche, atelier) */\n.c3d-carte .mini.atl{ --atl-x:calc(var(--gx) * 1.6 - 30%); --atl-y:calc(var(--gy) * 1.6 - 30%); }\n/* à la révélation : la souris si elle passe, sinon un lent va-et-vient */\n.card.atl:not(.fn-aucune) .carte-cadre{ animation:atlBalade 9s ease-in-out infinite;\n  --atl-x:var(--hx, calc(var(--atl-px) * 1%)); --atl-y:var(--hy, calc(var(--atl-py) * 1%)); }\n.atl-fond, .atl-a1, .atl-a2, .atl-reflet, .atl-glow, .atl-parts, .atl-scint{ position:absolute; pointer-events:none; display:block; font-style:normal; }\n.atl-fond{ inset:0; z-index:-1; }\n.atl-a1, .atl-a2{ inset:0; }\n.atl-reflet{ inset:0; z-index:4; border-radius:inherit; }\n.mini > .atl-reflet{ border-radius:10px; }\n.atl:not(.fn-aucune):not(.skin):not(.aurore) :is(.mini-int, .carte-int){ position:relative; isolation:isolate; }\n/* une carte qui porte un skin garde son skin ; une Aurore garde ses couleurs (seuls les reflets passent) */\n.atl.skin :is(.atl-fond, .atl-a1, .atl-a2, .atl-reflet, .atl-scint){ display:none; }\n.atl.aurore :is(.atl-fond, .atl-a1, .atl-a2){ display:none; }\n\n/* ---------- Encre (se gagne) : papier blanc, dessin à l'encre ---------- */\n.atl.fn-encre:not(.skin):not(.aurore) :is(.mini-int, .carte-int){ background:#fff; }\n.atl.fn-encre:not(.skin):not(.aurore) :is(.mini-art, .carte-art) > :is(svg, .art-photo){ filter:grayscale(1) contrast(1.5) brightness(.92); }\n.atl.fn-encre :is(.atl-fond, .atl-a1, .atl-a2, .atl-reflet){ display:none; }\n\n/* ---------- Chrome : l'argent poli, deux reflets francs qui glissent ---------- */\n.atl.fn-chrome:not(.skin):not(.aurore) :is(.mini-int, .carte-int){ background:linear-gradient(172deg, #FBFCFE 0%, #DCE3EB 38%, #F4F7FA 55%, #CDD6E1 100%); }\n.atl.fn-chrome .atl-fond{ background:repeating-linear-gradient(90deg, rgba(255,255,255,0) 0 1px, rgba(96,116,140,.08) 1px 2px),\n  repeating-linear-gradient(90deg, rgba(255,255,255,0) 0 6px, rgba(255,255,255,.45) 6px 7px); }\n.atl.fn-chrome:not(.skin):not(.aurore) :is(.mini-art, .carte-art) > :is(svg, .art-photo){ filter:grayscale(1) contrast(1.5) brightness(.96); }\n.atl.fn-chrome .atl-a1{ mix-blend-mode:multiply; background:linear-gradient(158deg, #7F93AE 0%, #F3F7FB 40%, #55677F 68%, #D9E3EE 100%); }\n.atl.fn-chrome .atl-a2{ mix-blend-mode:screen;\n  background:linear-gradient(112deg, transparent 30%, rgba(255,255,255,.95) 44%, rgba(214,228,242,.45) 50%, transparent 60%),\n    linear-gradient(112deg, transparent 62%, rgba(255,255,255,.55) 67%, transparent 72%);\n  background-size:300% 100%; background-position:var(--atl-x) 0; }\n.atl.fn-chrome:not(.skin):not(.aurore) :is(.mini-nom, .carte-nom){ background:linear-gradient(180deg, #7D8DA3 0%, #1B2738 52%, #8797AD 100%);\n  -webkit-background-clip:text; background-clip:text; color:transparent; }\n.atl.fn-chrome:not(.skin):not(.aurore) .carte-stats b{ color:#2A3646; }\n.atl.fn-chrome:not(.skin):not(.aurore) :is(.mini-dept, .carte-dept){ color:rgba(255,255,255,.45); }\n.atl.fn-chrome .atl-reflet{ mix-blend-mode:overlay;\n  background:linear-gradient(104deg, transparent 30%, rgba(30,44,64,.35) 39%, transparent 44%, rgba(255,255,255,.95) 48%, rgba(255,255,255,0) 54%),\n    linear-gradient(104deg, transparent 56%, rgba(255,255,255,.5) 60%, transparent 64%);\n  background-size:320% 100%; background-position:var(--atl-x) 0; }\n\n/* ---------- Cristal : facettes taillées, teinte de la rareté, éclats blancs ---------- */\n.atl.fn-cristal{ --teinte:#2F7CF6; }\n.atl.fn-cristal.commun{ --teinte:#7E8BA0; } .atl.fn-cristal.peucommun{ --teinte:#22A06B; }\n.atl.fn-cristal.epique{ --teinte:#9B5CF6; } .atl.fn-cristal.legendaire{ --teinte:#E0A21C; }\n.atl.fn-cristal:not(.skin):not(.aurore) :is(.mini-int, .carte-int){ background:#F3F6FA;\n  background:linear-gradient(160deg, #FFFFFF 0%, color-mix(in srgb, var(--teinte) 12%, #F3F6FA) 60%, color-mix(in srgb, var(--teinte) 26%, #E6ECF4) 100%); }\n.atl.fn-cristal .atl-fond{ opacity:.165; background:var(--teinte);\n  -webkit-mask:url('atelier-facettes.svg') center / 100% 100% no-repeat; mask:url('atelier-facettes.svg') center / 100% 100% no-repeat; }\n.atl.fn-cristal .atl-a1{ display:none; }\n.atl.fn-cristal .atl-a2{ mix-blend-mode:overlay; opacity:.95; background:url('atelier-facettes.svg') center / 260% 230% no-repeat; }\n.atl.fn-cristal:not(.skin):not(.aurore) :is(.mini-nom, .carte-nom){ color:#0E1A2C; color:color-mix(in srgb, var(--teinte) 55%, #0E1A2C); }\n.atl.fn-cristal .atl-reflet{ mix-blend-mode:soft-light;\n  background:url('atelier-facettes.svg') center / 100% 100% no-repeat,\n    radial-gradient(circle at var(--atl-x) var(--atl-y), rgba(255,255,255,.9), rgba(255,255,255,0) 45%);\n  -webkit-mask:radial-gradient(circle at var(--atl-x) var(--atl-y), #000 0 22%, rgba(0,0,0,.35) 45%, rgba(0,0,0,.08) 75%);\n  mask:radial-gradient(circle at var(--atl-x) var(--atl-y), #000 0 22%, rgba(0,0,0,.35) 45%, rgba(0,0,0,.08) 75%); }\n.atl-scint{ inset:0; z-index:5; }\n.atl-scint i{ position:absolute; width:12px; height:12px; margin:-6px 0 0 -6px; opacity:0; filter:drop-shadow(0 0 3px rgba(255,255,255,.9));\n  background:radial-gradient(circle, #fff 0 1.5px, rgba(255,255,255,.55) 2.5px, transparent 5px); animation:atlScint 2.6s ease-in-out infinite; }\n.atl-scint i::before, .atl-scint i::after{ content:''; position:absolute; left:50%; top:50%; background:#fff; border-radius:1px; transform:translate(-50%, -50%); }\n.atl-scint i::before{ width:20px; height:1.5px; } .atl-scint i::after{ width:1.5px; height:20px; }\n.mini .atl-scint i{ width:10px; height:10px; margin:-5px 0 0 -5px; }\n.mini .atl-scint i::before{ width:16px; height:1.2px; } .mini .atl-scint i::after{ width:1.2px; height:16px; }\n.atl-scint .s1{ left:18%; top:22%; } .atl-scint .s2{ left:72%; top:14%; animation-delay:.6s; } .atl-scint .s3{ left:86%; top:48%; animation-delay:1.2s; }\n.atl-scint .s4{ left:30%; top:40%; animation-delay:1.9s; } .atl-scint .s5{ left:58%; top:84%; animation-delay:.9s; }\n.atl-scint .s6{ left:14%; top:88%; animation-delay:2.2s; } .atl-scint .s7{ left:90%; top:92%; animation-delay:1.5s; }\n@keyframes atlScint{ 0%, 70%, 100%{ opacity:0; transform:scale(.4); } 80%{ opacity:1; transform:scale(1); } 90%{ opacity:.2; transform:scale(.6); } }\n\n/* ---------- Or (plus tard, par un pass) : la feuille d'or ---------- */\n.atl.fn-or:not(.skin):not(.aurore) :is(.mini-art, .carte-art){ background:linear-gradient(140deg, #8A5A10, #F0B429 40%, #FFF1B8 55%, #C9952A 70%, #8A5A10); }\n.atl.fn-or:not(.skin):not(.aurore) :is(.mini-art, .carte-art) > svg rect{ opacity:0; }\n.atl.fn-or:not(.skin):not(.aurore) :is(.mini-art, .carte-art) > svg path{ stroke:rgba(255,248,220,.6); }\n.atl.fn-or :is(.atl-fond, .atl-a1, .atl-a2){ display:none; }\n.atl.fn-or:not(.skin):not(.aurore) :is(.mini-art, .carte-art):has(> .art-photo) > .atl-a1{ display:block; mix-blend-mode:multiply; opacity:.75;\n  background:linear-gradient(140deg, #C9952A, #FFE7A0 50%, #B7791F); }\n.atl.fn-or .atl-reflet{ mix-blend-mode:overlay; background:linear-gradient(115deg, transparent 35%, rgba(255,250,220,.75) 50%, transparent 65%);\n  background-size:300% 100%; background-position:var(--atl-x) 0; }\n\n/* ---------- Halos : dans une grille, une lueur fixe sur la carte elle-même ---------- */\n.mini.atl:not(.h-aucun):not(.atl-n1):not(.atl-n2){ box-shadow:0 8px 16px rgba(0,0,0,.35), 0 0 8px 1px var(--halo);\n  box-shadow:0 8px 16px rgba(0,0,0,.35), 0 0 8px 1.5px color-mix(in srgb, var(--halo) 65%, transparent); }\n/* en grand : la lueur qui respire, les étoiles qui jaillissent, les braises qui montent */\n.atl-glow{ inset:0; z-index:-1; border-radius:14px; }\n.mini > .atl-glow{ border-radius:10px; }\n.atl.h-lueur .atl-glow{ animation:atlLueur 2.4s ease-in-out infinite; }\n.mini.atl-n1.h-lueur .atl-glow{ animation-name:atlLueurPetit; }\n.mini.atl-n2.h-lueur .atl-glow{ animation-name:atlLueurMini; }\n@keyframes atlLueur{ 0%, 100%{ box-shadow:0 0 14px 2px color-mix(in srgb, var(--halo) 55%, transparent); } 50%{ box-shadow:0 0 36px 12px color-mix(in srgb, var(--halo) 85%, transparent); } }\n@keyframes atlLueurMini{ 0%, 100%{ box-shadow:0 0 11px 2px color-mix(in srgb, var(--halo) 55%, transparent); } 50%{ box-shadow:0 0 29px 10px color-mix(in srgb, var(--halo) 85%, transparent); } }\n@keyframes atlLueurPetit{ 0%, 100%{ box-shadow:0 0 6px 1px color-mix(in srgb, var(--halo) 55%, transparent); } 50%{ box-shadow:0 0 16px 5px color-mix(in srgb, var(--halo) 85%, transparent); } }\n@supports not (color: color-mix(in srgb, red 50%, blue)){\n  @keyframes atlLueur{ 0%, 100%{ box-shadow:0 0 14px 2px var(--halo); opacity:.55; } 50%{ box-shadow:0 0 36px 12px var(--halo); opacity:.85; } }\n  @keyframes atlLueurMini{ 0%, 100%{ box-shadow:0 0 11px 2px var(--halo); opacity:.55; } 50%{ box-shadow:0 0 29px 10px var(--halo); opacity:.85; } }\n  @keyframes atlLueurPetit{ 0%, 100%{ box-shadow:0 0 6px 1px var(--halo); opacity:.55; } 50%{ box-shadow:0 0 16px 5px var(--halo); opacity:.85; } }\n}\n.atl-parts{ inset:-34px; z-index:6; }\n.mini > .atl-parts{ inset:-26px; }\n.mini.atl-n1 > .atl-parts{ inset:-14px; }\n.atl-p{ position:absolute; display:block; opacity:0; font-style:normal; }\n.atl-p.etoile{ width:7px; height:7px; animation:atlEtoile 2.6s ease-out infinite; }\n.atl-p.etoile::before, .atl-p.etoile::after{ content:''; position:absolute; left:50%; top:50%; background:var(--halo); transform:translate(-50%, -50%); border-radius:2px; }\n.atl-p.etoile::before{ width:12px; height:2px; } .atl-p.etoile::after{ width:2px; height:12px; }\n.mini .atl-p.etoile::before{ width:10px; height:1.6px; } .mini .atl-p.etoile::after{ width:1.6px; height:10px; }\n.mini.atl-n1 .atl-p.etoile::before{ width:7px; height:1.2px; } .mini.atl-n1 .atl-p.etoile::after{ width:1.2px; height:7px; }\n@keyframes atlEtoile{ 0%{ opacity:0; transform:translate(0, 0) scale(.3); } 25%{ opacity:1; } 100%{ opacity:0; transform:translate(var(--dx), var(--dy)) scale(1) rotate(90deg); } }\n.atl-p.braise{ width:4px; height:4px; border-radius:50%; background:var(--halo); box-shadow:0 0 6px 2px var(--halo); animation:atlBraise 3s ease-in infinite; }\n.mini .atl-p.braise{ width:3.4px; height:3.4px; box-shadow:0 0 5px 1.6px var(--halo); }\n.mini.atl-n1 .atl-p.braise{ width:2.6px; height:2.6px; box-shadow:0 0 4px 1px var(--halo); }\n@keyframes atlBraise{ 0%{ opacity:0; transform:translate(0, 0); } 15%{ opacity:1; } 100%{ opacity:0; transform:translate(var(--dx), var(--dy)); } }\n\n@media (prefers-reduced-motion: reduce){\n  .card.atl .carte-cadre, .atl-glow, .atl-p, .atl-scint i, .atl-ec-rayons, .atl-ec-flash{ animation:none !important; }\n  .atl.h-lueur .atl-glow{ box-shadow:0 0 18px 4px var(--halo); }\n  .atl-parts, .atl-scint{ display:none; }\n}\n\n/* ---------- l'écran de l'atelier ---------- */\nhtml.atl-ouvert, html.atl-ouvert body{ overflow:hidden; }\n.atl-ecran{ position:fixed; inset:0; z-index:48; display:flex; flex-direction:column; background:var(--nuit); color:#EAF1F8;\n  font-family:var(--texte); opacity:0; transition:opacity .18s ease; }\n.atl-ecran[hidden]{ display:none; }\n.atl-ecran.visible{ opacity:1; }\n.atl-ecran p{ margin:0; }\n.atl-page{ flex:1; min-height:0; overflow-y:auto; overscroll-behavior:contain; -webkit-overflow-scrolling:touch;\n  box-sizing:border-box; padding:36px 24px 64px; }\n.atl-page > *{ max-width:1180px; margin-left:auto; margin-right:auto; }\n.atl-tete{ display:flex; gap:14px; align-items:flex-start; }\n.atl-tete-t{ display:flex; flex-direction:column; gap:10px; min-width:0; }\n.atl-retour{ flex:none; width:44px; height:44px; margin:-6px 0 0 -8px; border-radius:50%; border:0; background:transparent; color:#EAF1F8;\n  display:flex; align-items:center; justify-content:center; cursor:pointer; padding:0; }\n.atl-retour:hover{ background:rgba(169,188,212,.12); }\n.atl-retour svg{ width:22px; height:22px; stroke:currentColor; fill:none; stroke-width:2; stroke-linecap:round; stroke-linejoin:round; }\n.atl-fil{ font-size:13px; color:var(--brume); letter-spacing:.04em; }\n.atl-tete h1{ margin:0; font-family:var(--titre); font-weight:900; font-size:60px; line-height:.95; }\n.atl-intro{ max-width:64ch; color:var(--brume); font-size:15px; line-height:1.55; }\n.atl-test-c{ display:none; }\n.atl-test{ align-self:flex-start; padding:5px 12px; border-radius:999px; background:#2A2A2E; border:1px solid rgba(240,180,41,.5); color:#FFE08A; font-size:13px; font-weight:600; }\n.atl-corps{ display:flex; flex-wrap:wrap; gap:28px; align-items:flex-start; margin-top:28px; }\n.atl-gauche{ flex:1 1 380px; min-width:0; display:flex; flex-direction:column; gap:14px; }\n.atl-droite{ flex:999 1 520px; min-width:0; display:flex; flex-direction:column; gap:22px; }\n.atl-scene{ position:relative; min-height:520px; border-radius:20px; background:var(--nuit-2); border:1px solid rgba(169,188,212,.14);\n  display:flex; align-items:center; justify-content:center; overflow:hidden; }\n.atl-c3d{ position:relative; z-index:2; }\n.atl-scene .c3d{ --s:1.85 !important; }\n.atl-scene .c3d-aide{ display:none; }\n.atl-lbl{ font-size:12px; font-weight:600; letter-spacing:.1em; text-transform:uppercase; color:var(--brume); }\n.atl-lbl-essayer{ margin-top:4px !important; }\n.atl-chips{ display:flex; flex-wrap:wrap; gap:8px; }\n.atl-chip, .atl-seg{ min-height:44px; padding:0 14px; border-radius:999px; border:1px solid rgba(169,188,212,.3); background:transparent; color:#EAF1F8;\n  font-family:inherit; font-size:14px; font-weight:500; cursor:pointer; display:inline-flex; align-items:center; box-sizing:border-box; }\n.atl-chip.on, .atl-seg.on{ background:#EAF1F8; color:var(--nuit); border-color:#EAF1F8; }\n.atl-seg{ cursor:default; }\n.atl-essai{ display:flex; flex-direction:column; gap:6px; padding:14px 16px; border-radius:12px; background:#2A2A2E; border:1px solid rgba(240,180,41,.5); }\n.atl-essai-t{ font-weight:600; color:#FFE08A; }\n.atl-essai p:not(.atl-essai-t){ font-size:14px; line-height:1.45; color:#EAF1F8; }\n.atl-essai-pill{ display:none; }\n.atl-fam{ display:flex; flex-direction:column; gap:10px; }\n.atl-fam-tete{ display:flex; justify-content:space-between; align-items:baseline; gap:12px; }\n.atl-choisi{ font-size:14px; color:#FFE08A; }\n.atl-opts{ display:flex; flex-wrap:wrap; gap:8px; }\n.atl-opt{ display:flex; flex-direction:column; align-items:flex-start; justify-content:center; gap:3px; min-height:56px; padding:8px 13px; border-radius:11px;\n  border:1px solid rgba(169,188,212,.25); background:#13284A; color:#EAF1F8; font-family:inherit; font-size:15px; font-weight:600; cursor:pointer; text-align:left; }\n.atl-opt:hover{ border-color:rgba(169,188,212,.55); }\n.atl-opt.on{ border-color:var(--c-legendaire); background:#2A3346; box-shadow:inset 0 0 0 1px var(--c-legendaire); }\n.atl-opt.verrou .atl-opt-nom{ color:#C9D6E6; }\n.atl-badge{ display:inline-flex; align-items:center; gap:5px; font-size:12px; font-weight:500; white-space:nowrap; }\n.atl-badge svg{ width:11px; height:11px; stroke:currentColor; fill:none; stroke-width:2.2; }\n.b-inclus{ color:var(--brume); } .b-atoi, .b-gagner{ color:#7EE2B0; } .b-boutique{ color:#FFD56B; } .b-pass{ color:#D3B8FF; }\n.atl-couleurs{ display:flex; flex-direction:column; gap:6px; margin-top:12px; }\n.atl-sws{ display:flex; gap:4px; }\n.atl-sw{ width:44px; height:44px; border-radius:50%; border:2px solid transparent; background:transparent; display:flex; align-items:center; justify-content:center; cursor:pointer; padding:0; }\n.atl-sw span{ width:26px; height:26px; border-radius:50%; display:block; }\n.atl-sw.on{ border-color:#EAF1F8; }\n.atl-onglets{ display:none; }\n.atl-appliquer{ display:flex; flex-direction:column; gap:12px; border-top:1px solid rgba(169,188,212,.16); padding-top:18px; }\n.atl-actions{ display:flex; flex-wrap:wrap; gap:10px; align-items:center; margin-top:4px; }\n.atl-btn{ min-height:48px; padding:0 22px; border:0; border-radius:12px; background:var(--c-legendaire); color:var(--encre);\n  font-family:var(--titre); font-weight:800; font-size:20px; letter-spacing:.01em; cursor:pointer; }\n.atl-btn:disabled{ background:#2A3E5C; color:var(--brume); cursor:not-allowed; }\n.atl-btn.sec{ background:transparent; color:#FFD56B; box-shadow:inset 0 0 0 2px rgba(240,180,41,.55); }\n.atl-btn.sec:disabled{ color:var(--brume); box-shadow:inset 0 0 0 2px rgba(169,188,212,.25); }\n.atl-note{ max-width:62ch; font-size:13px; line-height:1.5; color:var(--brume); }\n.atl-eclat{ display:flex; flex-wrap:wrap; gap:20px; align-items:center; justify-content:space-between; margin-top:28px; padding:20px 22px; border-radius:18px;\n  background:var(--nuit-2); border:1px solid rgba(169,188,212,.14); }\n.atl-eclat-t{ flex:1 1 420px; min-width:0; display:flex; flex-direction:column; gap:6px; }\n.atl-eclat-h{ font-family:var(--titre); font-weight:800; font-size:26px; }\n.atl-eclat-t p:not(.atl-eclat-h):not(.atl-eclat-v){ max-width:70ch; font-size:14px; line-height:1.55; color:#C9D6E6; }\n.atl-eclat-v{ font-size:13px; color:#7EE2B0; }\n.atl-bas{ display:none; }\n.atl-retour:focus-visible, .atl-chip:focus-visible, .atl-opt:focus-visible, .atl-sw:focus-visible, .atl-btn:focus-visible, .atl-onglet:focus-visible{ outline:2px solid #fff; outline-offset:2px; }\n/* l'éclat, pour voir */\n.atl-ec-rayons{ position:absolute; left:50%; top:50%; width:540px; height:540px; margin:-270px 0 0 -270px; border-radius:50%; pointer-events:none; z-index:1;\n  background:repeating-conic-gradient(from var(--bx-ang), rgba(255,224,138,0) 0 10deg, rgba(255,224,138,.55) 10deg 14deg);\n  -webkit-mask:radial-gradient(circle, #000 18%, transparent 66%); mask:radial-gradient(circle, #000 18%, transparent 66%);\n  animation:atlRayons 1.6s ease-out forwards, bxTourne 6s linear infinite; }\n@keyframes atlRayons{ 0%{ opacity:0; transform:scale(.4); } 25%{ opacity:1; transform:scale(1.05); } 100%{ opacity:0; transform:scale(1.3); } }\n.atl-ec-flash{ position:absolute; inset:0; background:#fff; opacity:0; pointer-events:none; z-index:6; animation:atlFlash .7s ease-out; }\n@keyframes atlFlash{ 0%{ opacity:.7; } 100%{ opacity:0; } }\n\n/* téléphone : la carte, les familles en onglets, un bouton en bas */\n@media (max-width: 760px){\n  .atl-page{ padding:0 0 8px; }\n  .atl-page > *{ max-width:none; }\n  .atl-tete{ align-items:center; gap:4px; padding:12px 10px 4px; }\n  .atl-retour{ margin:0; }\n  .atl-tete h1{ font-size:28px; line-height:1; }\n  .atl-fil, .atl-intro{ display:none; }\n  .atl-test{ font-size:12px; padding:3px 10px; }\n  .atl-test-l{ display:none; } .atl-test-c{ display:inline; }\n  .atl-tete-t{ flex-direction:row; align-items:center; gap:10px; flex-wrap:wrap; }\n  .atl-corps{ display:block; margin:0; }\n  .atl-gauche{ display:block; }\n  .atl-scene{ height:316px; min-height:0; border:0; border-radius:0; background:none; }\n  .atl-scene .c3d{ --s:1.2 !important; }\n  .atl-lbl-essayer, .atl-chips-cartes{ display:none; }\n  .atl-essai{ display:none; }\n  .atl-essai-pill{ display:block; position:absolute; left:50%; bottom:6px; transform:translateX(-50%); z-index:7; max-width:calc(100% - 24px);\n    padding:5px 12px; border-radius:999px; background:#2A2A2E; border:1px solid rgba(240,180,41,.5); color:#FFE08A; font-size:12.5px; font-weight:600;\n    white-space:nowrap; overflow:hidden; text-overflow:ellipsis; box-sizing:border-box; }\n  .atl-droite{ display:block; }\n  .atl-onglets{ display:flex; gap:4px; margin:8px 16px 0; padding:4px; border-radius:13px; background:var(--nuit-2); }\n  .atl-onglet{ flex:1; min-height:44px; border:0; border-radius:10px; background:transparent; color:var(--brume); font-family:inherit; font-size:14px; font-weight:600; cursor:pointer; }\n  .atl-onglet.on{ background:#EAF1F8; color:var(--nuit); }\n  .atl-fam{ display:none; padding:12px 16px 0; gap:8px; }\n  .atl-fam.actif{ display:flex; }\n  .atl-fam-tete{ display:none; }\n  .atl-opts{ flex-direction:column; gap:8px; }\n  .atl-opt{ flex-direction:row; align-items:center; justify-content:space-between; gap:10px; min-height:48px; padding:0 14px; border-radius:12px;\n    border-color:rgba(169,188,212,.18); width:100%; box-sizing:border-box; }\n  .atl-badge{ font-size:12.5px; }\n  .atl-couleurs{ flex-direction:row; align-items:center; gap:2px; margin-top:2px; }\n  .atl-couleurs .atl-lbl{ font-size:13px; letter-spacing:0; text-transform:none; font-weight:400; margin-right:6px; }\n  .atl-sws{ gap:2px; }\n  .atl-sw span{ width:24px; height:24px; }\n  .atl-appliquer, .atl-eclat{ display:none; }\n  .atl-bas{ display:flex; flex:none; flex-direction:column; gap:8px; padding:12px 16px max(22px, env(safe-area-inset-bottom)); border-top:1px solid rgba(169,188,212,.14); background:var(--nuit); }\n  .atl-bas p{ font-size:13px; color:var(--brume); text-align:center; }\n  .atl-bas .atl-btn{ width:100%; min-height:50px; border-radius:13px; }\n}\n\n/* ---------- l'atelier dans Personnaliser et dans la boutique ---------- */\n.gr-atelier{ display:flex; gap:14px; align-items:center; padding:12px 14px; border-radius:14px;\n  background:linear-gradient(120deg, rgba(240,180,41,.12), rgba(15,31,56,.55) 62%); border:1.5px solid rgba(240,180,41,.35); }\n.gr-atelier .gr-at-vig{ margin:0; flex:none; }\n.gr-at-txt{ display:grid; gap:4px; justify-items:start; min-width:0; }\n.gr-at-txt b{ font-family:var(--titre); font-weight:800; font-size:1.45rem; line-height:1; }\n.gr-at-txt span{ color:var(--brume); font-size:.84rem; line-height:1.35; }\n.gr-at-txt .bq-btn{ margin:6px 0 0; }\n.atl-vig .mini, .gr-at-vig .mini{ content-visibility:visible; }\n/* dans la boutique, un halo à étoiles ou à braises se voit aussi à sa lueur */\n.atl-vig .mini.atl:is(.h-etoiles, .h-braises) > .atl-glow{ box-shadow:0 0 12px 3px var(--halo); opacity:.7; }\n"
